SINA_SMART["anat3-facial-muscles"] = {"lecture":"anat3-facial-muscles","title":"Muscles of the facio-maxillary region","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"anat3-facial-muscles:s0","text":"Describe and explain: The big picture","topic":"The big picture","sec":0,"importance":"standard","highYield":"untested"},{"id":"anat3-facial-muscles:s1","text":"Describe and explain: What the lecture asks you to do","topic":"What the lecture asks you to do","sec":1,"importance":"standard","highYield":"untested"},{"id":"anat3-facial-muscles:e0","text":"Facial expression = CN VII. Mastication = V3. Levator palpebrae superioris is the odd one out: CN III.","topic":"Facial muscles: function and structure","sec":2,"importance":"core","highYield":"untested"},{"id":"anat3-facial-muscles:e1","text":"Facial muscles are subcutaneous, arise from bone or fascia and insert into skin.","topic":"Facial muscles: function and structure","sec":2,"importance":"core","highYield":"untested"},{"id":"anat3-facial-muscles:e4","text":"Corrugator supercilii is the frowning muscle; procerus makes transverse wrinkles over the bridge of the nose; mentalis is the pouting muscle.","topic":"Functional groups of facial muscles","sec":3,"importance":"core","highYield":"untested"},{"id":"anat3-facial-muscles:e2","text":"Occipitofrontalis: two bellies joined by the galea aponeurotica; the frontal belly has no bony attachment.","topic":"Scalp and eyelids","sec":4,"importance":"core","highYield":"untested"},{"id":"anat3-facial-muscles:e3","text":"Orbicularis oculi: palpebral part closes the lids gently and involuntarily; orbital part closes them forcefully and is voluntary.","topic":"Scalp and eyelids","sec":4,"importance":"core","highYield":"untested"},{"id":"anat3-facial-muscles:s5","text":"Describe and explain: Muscles of the nose","topic":"Muscles of the nose","sec":5,"importance":"standard","highYield":"untested"},{"id":"anat3-facial-muscles:e5","text":"Buccinator: from the maxilla, mandible and pterygomandibular raphe; keeps food between the teeth, blows air out, used in suckling.","topic":"Muscles of the mouth","sec":6,"importance":"core","highYield":"untested"},{"id":"anat3-facial-muscles:s7","text":"Describe and explain: Ear muscles and platysma","topic":"Ear muscles and platysma","sec":7,"importance":"standard","highYield":"untested"},{"id":"anat3-facial-muscles:e6","text":"Facial nerve branches: temporal, zygomatic, buccal, marginal mandibular, cervical (the cervical branch supplies the platysma).","topic":"Branches of the facial nerve and what they supply","sec":8,"importance":"core","highYield":"untested"},{"id":"anat3-facial-muscles:e7","text":"Four muscles of mastication: temporalis, masseter, lateral pterygoid, medial pterygoid.","topic":"Muscles of mastication","sec":9,"importance":"core","highYield":"untested"},{"id":"anat3-facial-muscles:e8","text":"Temporalis inserts on the coronoid process; masseter on the angle; lateral pterygoid on the neck and disc; medial pterygoid on the medial surface of the ramus.","topic":"Muscles of mastication","sec":9,"importance":"core","highYield":"untested"},{"id":"anat3-facial-muscles:e10","text":"TMJ ligaments: lateral (prevents posterior dislocation), sphenomandibular, stylomandibular.","topic":"The temporomandibular joint","sec":10,"importance":"core","highYield":"untested"},{"id":"anat3-facial-muscles:e11","text":"Upper part of the TMJ: protrusion and retraction. Lower part: elevation and depression, depression mostly by gravity.","topic":"The temporomandibular joint","sec":10,"importance":"core","highYield":"untested"},{"id":"anat3-facial-muscles:e12","text":"In TMJ dislocation the mandibular head moves anteriorly and the patient cannot close the mouth.","topic":"The temporomandibular joint","sec":10,"importance":"core","highYield":"untested"},{"id":"anat3-facial-muscles:e9","text":"TMJ: articular disc, two synovial cavities, fibrocartilage-covered surfaces.","topic":"The temporomandibular joint","sec":10,"importance":"core","highYield":"untested"}],"vmap":{},"mlevel":{"8n2mck":"a","r7lg3c":"a","vovy4d":"a","1hx5gxv":"a","14hs1sh":"a","5k3fxu":"a","bk9rot":"a","1ax81p6":"a","ael5j3":"a","sgk86u":"a","29g8ei":"a","1tqwkb5":"a","qnjin2":"a","100ixh4":"a","1w5jdp2":"a","fmtvcp":"a","fyzpna":"a","17p2y26":"a","1y456q5":"a","1ap8hk0":"a"},"mapCounts":{"verified":0,"auto":20,"ambiguous":0,"missing":0},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"anat3-facial-muscles:s0":{"s":0,"u":["Two different muscle groups live in this region and it is worth keeping them apart from the first minute.","Muscles of facial expression: thin, subcutaneous, inserting into skin, supplied by the facial nerve (CN VII) ."],"dp":[{"h":"Why facial muscles and chewing muscles have different nerves","t":"The two groups come from different pharyngeal arches in the embryo. The muscles of facial expression develop from the second arch, which is why they follow the facial nerve. The muscles of mastication develop from the first arch, which follows the trigeminal nerve, so they take V3. Knowing the arch makes the nerve impossible to forget. Sources: TeachMeAnatomy, The facial nerve; Brainscape, Muscles of mastication (first arch)."}]},"anat3-facial-muscles:s1":{"s":1,"u":["Discuss the muscles of facial expression and their innervation.","Relate the muscles of mastication to the actions at the temporomandibular joint."],"dp":[]},"anat3-facial-muscles:e0":{"s":2,"u":["Facial expression = CN VII. Mastication = V3. Levator palpebrae superioris is the odd one out: CN III.","All of them are supplied by the facial nerve (CN VII) .","They control the expressions of the face, which is why they are also called the muscles of facial expression or mimetic muscles."],"dp":[{"h":"Note","t":"Facial expression = CN VII (subcutaneous, insert into skin). Mastication = V3 (attached to bone). Levator palpebrae = CN III , the odd one out."},{"h":"Note","t":"Buccinator is a muscle of facial expression (CN VII) even though it helps chewing; the buccal nerve of V3 only carries sensation from the cheek."}]},"anat3-facial-muscles:e1":{"s":2,"u":["Facial muscles are subcutaneous, arise from bone or fascia and insert into skin.","They are subcutaneous, lying in the superficial fascia, with origins from bone or fascia and insertions into the skin.","They control the expressions of the face, which is why they are also called the muscles of facial expression or mimetic muscles."],"dp":[]},"anat3-facial-muscles:e4":{"s":3,"u":["Corrugator supercilii is the frowning muscle; procerus makes transverse wrinkles over the bridge of the nose; mentalis is the pouting muscle.","Eyelid: Orbicularis oculi, corrugator supercilii, levator palpebrae superioris.","Nose: Nasalis, procerus, depressor septi, dilator naris (anterior and posterior)."],"dp":[{"h":"Memory aid","t":"Corrugator = frowning; procerus = wrinkles across the nasal bridge; mentalis = pouting; zygomaticus major = smiling; risorius = pulls the angle sideways."}]},"anat3-facial-muscles:e2":{"s":4,"u":["Occipitofrontalis: two bellies joined by the galea aponeurotica; the frontal belly has no bony attachment.","Its two bellies are joined by the galea aponeurotica .","Frontal belly: Origin = Galea aponeurotica (no bony attachment); Insertion = Skin of the eyebrows; medial fibres blend with procerus, lateral fibres with corrugator and orbicularis oculi; Action = Wrinkles the forehead, raises the eyebrows."],"dp":[]},"anat3-facial-muscles:e3":{"s":4,"u":["Orbicularis oculi: palpebral part closes the lids gently and involuntarily; orbital part closes them forcefully and is voluntary.","Orbicularis oculi, palpebral part: Origin = Medial palpebral ligament; Insertion = Lateral palpebral raphe; Action = Closes the lids gently, as in blinking or sleep; involuntary.","Orbicularis oculi, orbital part: Origin = Nasal part of the frontal bone, frontal process of the maxilla, medial palpebral ligament; Insertion = An uninterrupted ellipse around the orbit; Action = Closes the eye forcefully, wrinkling the forehead; under conscious control."],"dp":[{"h":"Note","t":"Orbicularis oculi : palpebral part = gentle, involuntary blink; orbital part = forced, voluntary closure. Orbicularis oris closes the lips; buccinator keeps food between the teeth (cheek muscle, VII not V)."}]},"anat3-facial-muscles:s5":{"s":5,"u":["Nasalis, transverse part: Origin = Maxilla just lateral to the nose; Insertion = Aponeurosis across the dorsum of the nose, joining the muscle of the other side; Action = Compresses the nasal aperture.","Nasalis, alar part: Origin = Maxilla over the lateral incisor; Insertion = Alar cartilage of the nose; Action = Draws the cartilage downward and laterally, opening the nostril."],"dp":[]},"anat3-facial-muscles:e5":{"s":6,"u":["Buccinator: from the maxilla, mandible and pterygomandibular raphe; keeps food between the teeth, blows air out, used in suckling.","Origin: the posterior parts of the maxilla and mandible and the pterygomandibular raphe, which separates it from the superior constrictor of the pharynx.","It compresses the cheeks so that food is kept under the teeth during chewing, expels air from the distended cheeks as in blowing a trumpet, helps in whistling and smiling, and in newborns is used to suckle."],"dp":[]},"anat3-facial-muscles:s7":{"s":7,"u":["Ear: anterior, superior and posterior auricular muscles.","Platysma: origin the upper part of the pectoral and deltoid fascia; its fibres run upward over the clavicle to insert into the base of the mandible and the skin of the lower face and lip."],"dp":[]},"anat3-facial-muscles:e6":{"s":8,"u":["Facial nerve branches: temporal, zygomatic, buccal, marginal mandibular, cervical (the cervical branch supplies the platysma)."],"dp":[{"h":"Where the facial nerve splits into its five branches","t":"The facial nerve leaves the skull at the stylomastoid foramen, enters the parotid gland and forms the parotid plexus, which divides into the five terminal branches. The nerve passes through the gland but does not supply it: the parotid is supplied by the glossopharyngeal nerve. That relationship is why parotid surgery risks facial palsy. Source: TeachMeAnatomy, The facial nerve."},{"h":"Memory aid","t":"Facial nerve branches: 'To Zanzibar By Motor Car' : Temporal, Zygomatic, Buccal, Marginal mandibular, Cervical (platysma)."}]},"anat3-facial-muscles:e7":{"s":9,"u":["Four muscles of mastication: temporalis, masseter, lateral pterygoid, medial pterygoid.","Medial pterygoid: Origin = Deep head: medial surface of the lateral pterygoid plate and the palatine bone.","Inferior head: lateral pterygoid plate; Insertion = Pterygoid fovea of the neck of the mandible, and the capsule and articular disc of the TMJ; Main actions = Bilaterally protracts the mandible; one side alone pushes it to the opposite side."],"dp":[{"h":"Why depression of the jaw needs so little muscle","t":"The lateral pterygoid is the muscle that starts opening the mouth, but most of the movement is done by gravity. The digastric, geniohyoid and mylohyoid only step in when something resists, for example when you open against a hand pushing your chin up. Elevation is the opposite: it is a powerful movement needing the temporalis, masseter and medial pterygoid together. Sources: StatPearls, Anatomy, Head and Neck, Mastication muscles; lecture slides."}]},"anat3-facial-muscles:e8":{"s":9,"u":["Temporalis inserts on the coronoid process; masseter on the angle; lateral pterygoid on the neck and disc; medial pterygoid on the medial surface of the ramus.","Medial pterygoid: Origin = Deep head: medial surface of the lateral pterygoid plate and the palatine bone.","Inferior head: lateral pterygoid plate; Insertion = Pterygoid fovea of the neck of the mandible, and the capsule and articular disc of the TMJ; Main actions = Bilaterally protracts the mandible; one side alone pushes it to the opposite side."],"dp":[{"h":"Note","t":"Muscles of mastication: temporalis (coronoid; posterior fibres retract), masseter (angle; elevates), medial pterygoid (medial ramus; elevates), lateral pterygoid (neck and disc; protrudes)."}]},"anat3-facial-muscles:e10":{"s":10,"u":["TMJ ligaments: lateral (prevents posterior dislocation), sphenomandibular, stylomandibular.","A thickening of the capsule that prevents posterior dislocation.","Sphenomandibular ligament: from the spine of the sphenoid to the mandible."],"dp":[]},"anat3-facial-muscles:e11":{"s":10,"u":["Upper part of the TMJ: protrusion and retraction. Lower part: elevation and depression, depression mostly by gravity.","Lower part: elevation and depression , closing and opening the mouth.","Depression is mostly caused by gravity; the digastric, geniohyoid and mylohyoid assist if there is resistance."],"dp":[{"h":"Note","t":"Lateral pterygoid is the only muscle of mastication that helps open the mouth (by pulling the condyle and disc forward); the other three close it. Opening is otherwise mostly gravity plus digastric and geniohyoid/mylohyoid."}]},"anat3-facial-muscles:e12":{"s":10,"u":["In TMJ dislocation the mandibular head moves anteriorly and the patient cannot close the mouth.","Dislocation: a blow to the side of the face, yawning or taking a large bite can make the head of the mandible slip out of the mandibular fossa and be pulled anteriorly, so the patient cannot close the mouth."],"dp":[{"h":"Clinical","t":"TMJ dislocation is anterior (yawning, big bite): the condyle slips in front of the articular eminence and the mouth stays open."}]},"anat3-facial-muscles:e9":{"s":10,"u":["TMJ: articular disc, two synovial cavities, fibrocartilage-covered surfaces.","The articular surfaces are covered by fibrocartilage , not hyaline cartilage.","The joint has a unique mechanism: the articular surfaces never touch, because an articular disc splits the joint into two synovial cavities , each lined by its own synovial membrane."],"dp":[{"h":"Note","t":"TMJ : synovial joint with an articular disc making two cavities; surfaces covered by fibrocartilage . Upper cavity = gliding (protrusion/retraction); lower = hinge (elevation/depression). Lateral ligament prevents posterior dislocation."}]}},"meta":{"8n2mck":{"a":"recall","vg":"anat3-facial-muscles:e0/recall/1"},"r7lg3c":{"a":"recall","vg":"anat3-facial-muscles:e1/recall/1"},"vovy4d":{"a":"recall","vg":"anat3-facial-muscles:e2/recall/1"},"1hx5gxv":{"a":"recall","vg":"anat3-facial-muscles:e3/recall/1"},"14hs1sh":{"a":"recall","vg":"anat3-facial-muscles:e4/recall/1"},"5k3fxu":{"a":"recall","vg":"anat3-facial-muscles:e4/recall/2"},"bk9rot":{"a":"recall","vg":"anat3-facial-muscles:e5/recall/1"},"1ax81p6":{"a":"recall","vg":"anat3-facial-muscles:e5/recall/2"},"ael5j3":{"a":"recall","vg":"anat3-facial-muscles:e4/recall/3"},"sgk86u":{"a":"recall","vg":"anat3-facial-muscles:e0/recall/1"},"29g8ei":{"a":"recall","vg":"anat3-facial-muscles:e8/recall/1"},"1tqwkb5":{"a":"recall","vg":"anat3-facial-muscles:e8/recall/1"},"qnjin2":{"a":"recall","vg":"anat3-facial-muscles:e6/recall/1"},"100ixh4":{"a":"recall","vg":"anat3-facial-muscles:e9/recall/1"},"1w5jdp2":{"a":"relationship","vg":"anat3-facial-muscles:e11/relationship/1"},"fmtvcp":{"a":"recall","vg":"anat3-facial-muscles:e12/recall/1"},"fyzpna":{"a":"recall","vg":"anat3-facial-muscles:e7/recall/1"},"17p2y26":{"a":"recall","vg":"anat3-facial-muscles:e6/recall/2"},"1y456q5":{"a":"recall","vg":"anat3-facial-muscles:e5/recall/3"},"1ap8hk0":{"a":"recall","vg":"anat3-facial-muscles:e10/recall/1"}},"explRev":"6d77f8bdd861"};
